    let dir = tempfile::tempdir().map_err(|e| format!("tempdir: {e}"))?;
    let journal_path = dir.path().to_path_buf();

    {
        let journal = FjallJournal::open(&journal_path, None)
            .map_err(|e| format!("journal open: {e}"))?;

